// Landing band on /login: should be visible and not covered by anything.
await expect(page.getByRole('banner').first()).toBeVisible();

// Ops map controls on /ops/radar must sit above the map layers and be clickable.
await page.goto('/ops/radar');
const zoomIn = page.getByRole('button', { name: /zoom in/i });
await expect(zoomIn).toBeVisible();
await zoomIn.click({ timeout: 3000 }); // fails if another layer covers the control
const zoomOut = page.getByRole('button', { name: /zoom out/i });
await expect(zoomOut).toBeVisible();
await zoomOut.click({ timeout: 3000 });

// The controls' stack level must be above the page content (z-index set, not auto).
const group = page.getByRole('group', { name: /map controls/i });
await expect(group).toBeVisible();
await expect(group).not.toHaveCSS('z-index', 'auto');
